import compose from 'lodash/flowRight'
import {useEffect, useMemo} from 'react'
import {connect} from 'react-redux'
import type {EntryPointProps} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import withHook from '../../../hocs/withHook'
import {useRefetchablePreloadedQuery} from '../../../hooks/relay/useRefetchablePreloadedQuery'
import type {State} from '../../../reducers/types'
import {getBuildType, getIsSakuraUI} from '../../../selectors'
import type {BuildTypeId, BuildTypeInternalId} from '../../../types'
import {notNull} from '../../../utils/guards'
import {subscribeOnBuildTypeEvents} from '../../../utils/subscriber'
import {BUILD_TAGS_CHANGED} from '../../../utils/subscriptionEvents'
import {buildTypeTagsQuery} from '../../pages/CleanupProjectPage/Listings/Rules/CleanupForm/CleanupForm.queries'

import type {TagsListBuildTypeTagsQuery} from './__generated__/TagsListBuildTypeTagsQuery.graphql'
import TagsList from './TagsList'

export type TagsFiltersProps = {
  buildTypeId: BuildTypeId
  selected?: string | null | undefined
  onSelect?: (arg0: string | null | undefined) => unknown
  onReset?: () => unknown
}
type OwnProps = TagsFiltersProps & {
  buildTypeTagsQueryRef: PreloadedQuery<TagsListBuildTypeTagsQuery>
}
type StateProps = {
  internalId: BuildTypeInternalId | null | undefined
  isSakuraUI: boolean | null | undefined
}
type Props = OwnProps & StateProps

const mapStateToProps = (state: State, {buildTypeId}: OwnProps): StateProps => ({
  internalId: getBuildType(state, buildTypeId)?.internalId,
  isSakuraUI: getIsSakuraUI(state),
})

const TagsFilter = compose(
  connect(mapStateToProps),
  withHook(({internalId, selected, onReset, buildTypeTagsQueryRef}: Props) => {
    const [{buildTypeBuildTags}, refetch] = useRefetchablePreloadedQuery(
      buildTypeTagsQuery,
      buildTypeTagsQueryRef,
    )
    const tags = useMemo(
      () => buildTypeBuildTags?.tag?.map(tag => tag.name).filter(notNull) ?? [],
      [buildTypeBuildTags],
    )

    useEffect(() => {
      if (onReset != null && selected != null && !tags.includes(selected)) {
        onReset()
      }
    }, [onReset, selected, tags])

    useEffect(
      () =>
        internalId != null
          ? subscribeOnBuildTypeEvents(internalId, [BUILD_TAGS_CHANGED], () =>
              refetch(buildTypeTagsQueryRef.variables),
            )
          : undefined,
      [internalId, refetch, buildTypeTagsQueryRef.variables],
    )

    return {tags}
  }),
)(TagsList)

type Queries = {buildTypeTags: TagsListBuildTypeTagsQuery}

export default function TagsFiltersContainer({
  queries,
  props,
}: EntryPointProps<Queries, {}, TagsFiltersProps, {}>) {
  return <TagsFilter {...props} buildTypeTagsQueryRef={queries.buildTypeTags} />
}
export type TagsFiltersContainerComponent = typeof TagsFiltersContainer
